<?php if($canUpdate):?><script>document.addEventListener('click',function(e){const adminButton=e.target.closest('.update-clearance'),approverButton=e.target.closest('.approve-clearance'),button=adminButton||approverButton;if(!button)return;let item=$(button).data('json');if(adminButton){document.getElementById('clearanceDepartment').value=item.department_id||'';document.getElementById('clearanceResponsible').value=item.responsible_user_id||'';document.getElementById('clearanceRequirement').value=item.clearance_requirement||'';document.getElementById('clearanceMandatory').checked=Number(item.is_mandatory)===1}else{document.getElementById('approverClearanceId').value=item.id;document.getElementById('approverStatus').value=item.status;document.getElementById('approverAccountability').value=item.accountability_details||'';document.getElementById('approverComments').value=item.comments||'';bootstrap.Modal.getOrCreateInstance(document.getElementById('approverClearanceModal')).show()}},true);</script><?php endif;?>
